SHOW TABLES LIKE '%candle%';
SELECT p.id AS position_id, p.entry_price, p.stop_loss, p.take_profit, p.exit_price, (SELECT MAX(c.high_price) FROM candle c WHERE c.symbol=p.symbol AND c.interval_code='1m' AND c.open_time >= p.opened_at AND c.open_time < p.closed_at) AS hold_high, (SELECT MIN(c.low_price) FROM candle c WHERE c.symbol=p.symbol AND c.interval_code='1m' AND c.open_time >= p.opened_at AND c.open_time < p.closed_at) AS hold_low, (SELECT MAX(c.high_price) FROM candle c WHERE c.symbol=p.symbol AND c.interval_code='1m' AND c.open_time >= p.closed_at AND c.open_time < p.closed_at + INTERVAL 60 MINUTE) AS post60_high, (SELECT MIN(c.low_price) FROM candle c WHERE c.symbol=p.symbol AND c.interval_code='1m' AND c.open_time >= p.closed_at AND c.open_time < p.closed_at + INTERVAL 60 MINUTE) AS post60_low FROM paper_position p WHERE p.id IN (182,172,162,158,143,137) ORDER BY p.id